# The left fingers surround the white block and the carried stack is just above the center tabletop. Release the stack while grasping white, then lift both wrists to inspect the result.
obs = get_observation()
s = obs['state']
action = {'left_ee_pose': s['left_ee_pose'], 'right_ee_pose': s['right_ee_pose'], 'left_ee_joint_state': [0.0], 'right_ee_joint_state': [1.0]}
ended = False
for i in range(12):
    obs, reward, terminated, truncated, info = step(action)
    if terminated or truncated:
        ended = True
        break
if not ended:
    obs, reason = move_both({'right': [0.200, -0.260, 1.100] + down_q, 'left': [-0.354, -0.085, 1.035] + down_q}, {'right': 1.0, 'left': 0.0}, max_steps=30, max_translation=0.012)

contents.b8d6ffe8fbdccd34f799780eee67bebfa1dc7870:
# The right arm is clear. Center white over black, release at one-block support height, and lift enough to approach the nearby wooden block next.
obs, reason, used = move_ee('left', [-0.0206, -0.135, 0.987] + down_q, gripper=0.0, max_steps=15, max_translation=0.009, settle_steps=2, stall_steps=6)
if reason == 'reached':
    obs, reason, used = hold_ee('left', 1.0, max_steps=8)
    if reason == 'settled':
        obs, reason, used = move_ee('left', [-0.0206, -0.135, 1.045] + down_q, gripper=1.0, max_steps=9, max_translation=0.012, settle_steps=2)

