# The wooden block is slightly forward and right of the finger center. Correct that small offset, close, and lift clear of the two-block stack.
obs, reason, used = move_ee('left', [-0.055, -0.171, 0.944] + down_q, gripper=1.0, max_steps=4, max_translation=0.012, settle_steps=1)
if reason == 'reached':
    obs, reason, used = hold_ee('left', 0.0, max_steps=8)
    if reason == 'settled':
        obs, reason, used = move_ee('left', [-0.055, -0.171, 1.060] + down_q, gripper=0.0, max_steps=11, max_translation=0.015, settle_steps=1)

